B.b4r=new A.y("\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0432\u0432\u043e\u0434. \u041d\u0430\u0436\u0438\u043c\u0430\u0439\u0442\u0435 \u0430\u043f\u043f\u0430\u0440\u0430\u0442\u044b \u043d\u0430 \u0441\u0445\u0435\u043c\u0435 \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u043a\u043b\u044e\u0447\u0430\u0442\u0435\u043b\u0438 \u0432 \u0441\u043f\u0438\u0441\u043a\u0435. \xab\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0432\u0441\u0451\xbb \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0432\u0441\u0435 \u0432\u043d\u0435\u0448\u043d\u0438\u0435 \u0432\u0432\u043e\u0434\u044b \u0438 \u0437\u0430\u043c\u044b\u043a\u0430\u0435\u0442 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u044b \u0432\u043e \u0432\u0441\u0451\u043c \u043f\u0440\u043e\u0435\u043a\u0442\u0435; \xab\u0412\u044b\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0432\u0441\u0451\xbb \u043e\u0442\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0432\u0432\u043e\u0434\u044b \u0438 \u0440\u0430\u0437\u043c\u044b\u043a\u0430\u0435\u0442 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u044b. \u041e\u0440\u0430\u043d\u0436\u0435\u0432\u044b\u0439 \u2014 \u0444\u0430\u0437\u0430, \u0441\u0438\u043d\u0438\u0439 \u2014 \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0439 \u0441 \u0432\u0432\u043e\u0434\u043e\u043c N, \u0437\u0435\u043b\u0451\u043d\u044b\u0439 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044c \u2014 \u0435\u0441\u0442\u044c L \u0438 N \u043e\u0442 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0432\u043e\u0434\u0430. \u0421\u0435\u0440\u044b\u0439 \u2014 \u043f\u0438\u0442\u0430\u043d\u0438\u0435 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442, \u043a\u0440\u0430\u0441\u043d\u044b\u0439 \u2014 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u043e\u0432. PE \u043d\u0435 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442 N.\n\n\u041d\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u2014 \u0441\u0443\u043c\u043c\u0430 \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0445 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0445 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439, \u0431\u0435\u0437 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442\u0430 \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0441\u0442\u0438. \xab\u0412\u0441\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u044b\xbb \u2014 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0439 \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u043f\u0440\u0438 \u0437\u0430\u043c\u043a\u043d\u0443\u0442\u044b\u0445 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u0430\u0445 \u043e\u0442 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0445 \u0432\u0432\u043e\u0434\u043e\u0432. \u041b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0433\u0440\u0443\u043f\u043f\u044b \u0431\u0435\u0437 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0432\u043e\u0434\u043a\u0438 \u043f\u0438\u0442\u0430\u043d\u0438\u0435 \u043d\u0435 \u0441\u043e\u0437\u0434\u0430\u044e\u0442.\n\n\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0436\u0438\u043b \u0438\u0437 \xab\u041a\u043b\u0435\u043c\u043c\u044b \u043f\u0440\u0438\u0431\u043e\u0440\u043e\u0432\xbb \u043f\u0440\u0438\u043d\u0446\u0438\u043f\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u0441\u0445\u0435\u043c \u0438 \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u044f \u0449\u0438\u0442\u043e\u0432/\u043a\u043e\u0440\u043e\u0431\u043e\u043a. \u041d\u0435\u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044b\u0435 \u0436\u0438\u043b\u044b \u043d\u0435 \u0443\u0433\u0430\u0434\u044b\u0432\u0430\u044e\u0442\u0441\u044f. \u0414\u0430\u0442\u0447\u0438\u043a\u0438 \u0438 \u0440\u0430\u0434\u0438\u043e\u043a\u043e\u043c\u0430\u043d\u0434\u044b \u043d\u0435 \u0437\u0430\u043c\u044b\u043a\u0430\u044e\u0442 \u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u0438 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438. \u0413\u043b\u0430\u0432\u043d\u044b\u0435 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u044b \u0440\u0435\u043b\u0435 \u0438 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043e\u0440\u043e\u0432 \u0437\u0430\u0434\u0430\u044e\u0442\u0441\u044f \u0432\u0440\u0443\u0447\u043d\u0443\u044e, \u0432\u0441\u0435 \u043a\u043b\u0430\u0432\u0438\u0448\u0438 \u043e\u0431\u044b\u0447\u043d\u043e\u0433\u043e \u0432\u044b\u043a\u043b\u044e\u0447\u0430\u0442\u0435\u043b\u044f \u0438\u0441\u0445\u043e\u0434\u043d\u043e \u0437\u0430\u043c\u043a\u043d\u0443\u0442\u044b.\n\n\u042d\u0442\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0441\u0432\u044f\u0437\u043d\u043e\u0441\u0442\u0438 \u0438 \u0440\u0430\u0441\u0447\u0451\u0442\u043d\u043e\u0439 \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u0438: \u0442\u043e\u043a \u041a\u0417, \u0443\u0442\u0435\u0447\u043a\u0438, \u0432\u0440\u0435\u043c\u044f \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u0438 \u0440\u0430\u0431\u043e\u0442\u0443 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u0438\u043a\u0438 \u043e\u043d\u0430 \u043d\u0435 \u043c\u043e\u0434\u0435\u043b\u0438\u0440\u0443\u0435\u0442. \u041f\u0435\u0440\u0435\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u043d\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u0432 \u043f\u0440\u043e\u0435\u043a\u0442.",null,null,null,null,null,null,null,null,null,null)
B.aVx=new A.vC(B.F,null,null,null,null,B.b4r,B.A,null)
B.b4O=new A.y("\u041a\u043e\u043c\u043f\u044c\u044e\u0442\u0435\u0440: W A S D \u2014 \u0438\u0434\u0442\u0438, \u0441\u0442\u0440\u0435\u043b\u043a\u0438 \u2191 \u2193 \u2014 \u0432\u043f\u0435\u0440\u0451\u0434 / \u043d\u0430\u0437\u0430\u0434, \u2190 \u2192 \u2014 \u043f\u043e\u0432\u043e\u0440\u043e\u0442. \u0417\u0430\u0436\u043c\u0438\u0442\u0435 \u043c\u044b\u0448\u044c \u0438 \u0432\u0435\u0434\u0438\u0442\u0435 \u0434\u043b\u044f \u043e\u0431\u0437\u043e\u0440\u0430. E \u2014 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c, L \u2014 \u0441\u0432\u0435\u0442 \u0432 \u043a\u043e\u043c\u043d\u0430\u0442\u0435, Esc \u2014 \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u0432 \u0440\u0435\u0434\u0430\u043a\u0442\u043e\u0440.\n\n\u041a\u043d\u043e\u043f\u043a\u0438 \u2212 / + \u0438 \u043a\u043e\u043b\u0435\u0441\u043e \u043c\u044b\u0448\u0438 \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u044e\u0442 \u0438\u043b\u0438 \u0441\u0443\u0436\u0430\u044e\u0442 \u0443\u0433\u043e\u043b \u043e\u0431\u0437\u043e\u0440\u0430. \u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u0447\u0438\u0441\u043b\u043e \u0433\u0440\u0430\u0434\u0443\u0441\u043e\u0432 \u0434\u043b\u044f \u043f\u043e\u043b\u0437\u0443\u043d\u043a\u0430 \u0438 \u0433\u043e\u0442\u043e\u0432\u044b\u0445 \u0440\u0430\u043a\u0443\u0440\u0441\u043e\u0432. \u0412 \u043c\u0435\u043d\u044e \xab\u0412 \u0446\u0435\u043d\u0442\u0440 \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u043a\u043e\u043c\u043d\u0430\u0442\u044b\xbb \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u043e\u0439\u0442\u0438 \u043e\u0442 \u0441\u0442\u0435\u043d\u044b \u0432 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u0443\u044e \u0442\u043e\u0447\u043a\u0443.\n\n\u0422\u0435\u043b\u0435\u0444\u043e\u043d: \u043b\u0435\u0432\u044b\u0439 \u0434\u0436\u043e\u0439\u0441\u0442\u0438\u043a \u2014 \u0438\u0434\u0442\u0438; \u0432\u0435\u0434\u0438\u0442\u0435 \u043f\u0430\u043b\u044c\u0446\u0435\u043c \u043f\u043e \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u044e \u0434\u043b\u044f \u043e\u0431\u0437\u043e\u0440\u0430. \u041a\u043d\u043e\u043f\u043a\u0430 \u0434\u0432\u0435\u0440\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043d\u0430 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0443\u044e \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0443\u044e \u0434\u0432\u0435\u0440\u044c. \u041d\u0430\u0432\u0435\u0434\u0438\u0442\u0435 \u043f\u0440\u0438\u0446\u0435\u043b \u043d\u0430 \u0441\u0432\u0435\u0442\u0438\u043b\u044c\u043d\u0438\u043a, \u0442\u043e\u0440\u0448\u0435\u0440 \u0438\u043b\u0438 \u0432\u044b\u043a\u043b\u044e\u0447\u0430\u0442\u0435\u043b\u044c \u0438 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u043a\u043d\u043e\u043f\u043a\u0443 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f. \u0412\u044b\u043a\u043b\u044e\u0447\u0430\u0442\u0435\u043b\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u043c\u0438 \u043a\u0430\u0431\u0435\u043b\u0435\u043c \u0441\u0432\u0435\u0442\u0438\u043b\u044c\u043d\u0438\u043a\u0430\u043c\u0438 \u0447\u0435\u0440\u0435\u0437 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0443\u044e \u043a\u043e\u0440\u043e\u0431\u043a\u0443; \u0431\u0435\u0437 \u0441\u0432\u044f\u0437\u0435\u0439 \u2014 \u0441\u0432\u0435\u0442\u043e\u043c \u0441\u0432\u043e\u0435\u0439 \u043a\u043e\u043c\u043d\u0430\u0442\u044b. \u041a\u043d\u043e\u043f\u043a\u0430 \xab\u0421\u0432\u0435\u0442\u0438\u043b\u044c\u043d\u0438\u043a\u0438\xbb \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u043a\u043b\u044e\u0447\u0430\u0442\u0435\u043b\u0438 \u0432\u0441\u0435\u0445 \u043f\u0440\u0438\u0431\u043e\u0440\u043e\u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u0433\u043e \u044d\u0442\u0430\u0436\u0430.\n\n\u0414\u0435\u043d\u044c / \u043d\u043e\u0447\u044c \u043c\u0435\u043d\u044f\u0435\u0442 \u0444\u043e\u043d\u043e\u0432\u043e\u0435 \u043e\u0441\u0432\u0435\u0449\u0435\u043d\u0438\u0435. \u0421\u0432\u0435\u0442\u0438\u043b\u044c\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442 \u0443\u0441\u043b\u043e\u0432\u043d\u043e\u0435 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u0435 \u043e\u0441\u0432\u0435\u0449\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u043e\u0441\u0432\u0435\u0449\u0451\u043d\u043d\u043e\u0441\u0442\u0438 \u0438 \u0442\u0435\u043d\u0435\u0439. \u0414\u0432\u0435\u0440\u0438 \u0438 \u0441\u0432\u0435\u0442 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u0432 \u043f\u0440\u043e\u0435\u043a\u0442\u0435; \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c \u0432 \u0440\u0435\u0434\u0430\u043a\u0442\u043e\u0440\u0435. \u0412 \u043c\u0435\u043d\u044e \u0432\u044b\u0431\u043e\u0440\u0430 \u043a\u043e\u043c\u043d\u0430\u0442\u044b \u043c\u043e\u0436\u043d\u043e \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u043f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e.",null,null,null,null,null,null,null,null,null,null)
